-- Seed de contrat multisite/multilingue deterministe.
PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;
DELETE FROM public_content_snapshots WHERE site_id IN (10,11);
DELETE FROM search_documents WHERE site_id IN (10,11);
DELETE FROM seo_metadata WHERE site_id IN (10,11);
DELETE FROM routes WHERE site_id IN (10,11);
DELETE FROM content_slug_registry WHERE site_id IN (10,11);
DELETE FROM content_entry_taxonomy_terms WHERE entry_id BETWEEN 1000 AND 1199;
DELETE FROM content_entry_publications WHERE entry_id BETWEEN 1000 AND 1199;
DELETE FROM content_entry_working_revisions WHERE entry_id BETWEEN 1000 AND 1199;
DELETE FROM menu_item_localizations WHERE menu_item_id BETWEEN 10000 AND 11999;
DELETE FROM menu_items WHERE menu_id IN (1010,1011,1110,1111);
DELETE FROM menus WHERE site_id IN (10,11);
DELETE FROM taxonomy_term_localizations WHERE site_id IN (10,11);
DELETE FROM taxonomy_terms WHERE taxonomy_id IN (1010,1110);
DELETE FROM content_type_taxonomies WHERE taxonomy_id IN (1010,1110);
DELETE FROM taxonomies WHERE site_id IN (10,11);
DELETE FROM media_asset_localizations WHERE media_id IN (1010,1110);
DELETE FROM media_assets WHERE site_id IN (10,11);
DELETE FROM media_variant_presets WHERE site_id IN (10,11);
DELETE FROM media_folders WHERE site_id IN (10,11);
DELETE FROM content_entry_localizations WHERE entry_id BETWEEN 1000 AND 1199;
DELETE FROM revisions WHERE resource_type='content_entry' AND resource_id BETWEEN 1000 AND 1199;
DELETE FROM content_entries WHERE site_id IN (10,11);
DELETE FROM site_settings WHERE site_id IN (10,11);
DELETE FROM site_localizations WHERE site_id IN (10,11);
DELETE FROM site_languages WHERE site_id IN (10,11);
DELETE FROM site_domains WHERE site_id IN (10,11);
DELETE FROM sites WHERE site_key IN ('site_a','site_b');
-- Presets responsives natifs par sous-site. Sans ces lignes, les uploads Site A/B
-- n'ont pas la même politique de variants que le site central.
SELECT s.id, v.preset_key, v.width, v.height, v.format, v.quality, v.mode, v.sort_order, 1
FROM sites s
JOIN (
    SELECT 'content_480' AS preset_key, 480 AS width, NULL AS height, 'webp' AS format, 82 AS quality, 'fit' AS mode, 10 AS sort_order UNION ALL
    SELECT 'content_768', 768, NULL, 'webp', 82, 'fit', 20 UNION ALL
    SELECT 'content_1024', 1024, NULL, 'webp', 82, 'fit', 30 UNION ALL
    SELECT 'content_1280', 1280, NULL, 'webp', 82, 'fit', 40 UNION ALL
    SELECT 'content_1600', 1600, NULL, 'webp', 82, 'fit', 50 UNION ALL
    SELECT 'hero_640', 640, NULL, 'webp', 82, 'fit', 110 UNION ALL
    SELECT 'hero_960', 960, NULL, 'webp', 82, 'fit', 120 UNION ALL
    SELECT 'hero_1280', 1280, NULL, 'webp', 82, 'fit', 130 UNION ALL
    SELECT 'hero_1920', 1920, NULL, 'webp', 82, 'fit', 140 UNION ALL
    SELECT 'og_1200x630', 1200, 630, 'webp', 82, 'crop', 210
) v
WHERE s.site_key IN ('site_a','site_b')
ON CONFLICT(site_id, preset_key) DO UPDATE SET
    width=excluded.width,
    height=excluded.height,
    format=excluded.format,
    quality=excluded.quality,
    mode=excluded.mode,
    sort_order=excluded.sort_order,
    is_active=1,
    updated_at=CURRENT_TIMESTAMP;
COMMIT;

DELETE FROM site_settings WHERE namespace = 'api' AND setting_key = 'cors_allowed_origins' AND site_id IN (10,11);
